// Probe a list of targets in parallel and write a single combined record
// to /data/chatin/_telemetry/. Uses the n8n-builtin this.helpers.httpRequest
// API instead of the raw http/https core modules: n8n's hardened Code-node
// sandbox blocks the raw http module (runtime error: Module http is
// disallowed), which silently broke this monitor every 5 minutes. fs + path
// stay on the allow-list. The OLLAMA target is hardcoded to its docker default
// (was the OLLAMA_BASE_URL env read, also a sandbox-blocked access on this node)
// per the wf30/31/32 precedent in commit 1edb8e1; it lifts to a Config Set
// node later per Decision 1 of
// docs/99-session-notes/2026-06-01-research-review-n8n-fix-patterns.md.
// Binding: EXECUTION-OUTCOME-OBSERVABILITY -- the thing that watches the
// system must be able to watch itself.
//
// The probes are FROM-THE-NAS -- what the Synology can reach, not what the
// family devices can reach (that's the PWA NetworkStatus component's job).
// Together they tell us whether a failure is on the NAS side or device side.

const fs = require('fs');
const path = require('path');

// this.helpers is the n8n execution context. Capture it so the nested probe
// closures keep the binding when fired in parallel via Promise.all.
const self = this;

const TELEMETRY_DIR = '/data/chatin/_telemetry';
fs.mkdirSync(TELEMETRY_DIR, { recursive: true });

const TIMEOUT_MS = 5000;

// Targets we care about from the NAS's perspective.
const targets = [
  { key: 'internet', method: 'GET', url: 'https://www.cloudflare.com/cdn-cgi/trace' },
  { key: 'ollama',   method: 'GET', url: 'http://ollama:11434/api/tags' },
  { key: 'n8n_self', method: 'GET', url: 'http://127.0.0.1:5678/healthz' },
  { key: 'dsm',      method: 'GET', url: 'http://192.168.1.26:5000/' }
];

const probe = async ({ key, method, url }) => {
  const started = Date.now();
  try {
    const res = await self.helpers.httpRequest({
      method,
      url,
      timeout: TIMEOUT_MS,
      returnFullResponse: true,      // expose statusCode without parsing body
      ignoreHttpStatusErrors: true,  // 4xx/5xx return as data, not a throw
      skipSslCertificateValidation: true // tolerate Synology self-signed certs
    });
    const ms = Date.now() - started;
    const status = res.statusCode;
    return { key, ok: status >= 200 && status < 500, status, ms };
  } catch (err) {
    // Timeout, DNS failure, or refused connection lands here. If the error
    // still carries a status code, surface it; otherwise status 0 = unreachable.
    const ms = Date.now() - started;
    const status = (err && (err.statusCode || (err.response && err.response.statusCode))) || 0;
    return {
      key,
      ok: status >= 200 && status < 500 && status !== 0,
      status,
      ms,
      error: String((err && err.message) || err)
    };
  }
};

return (async () => {
  const probedAt = new Date().toISOString();
  const results = await Promise.all(targets.map(probe));

  const summary = {
    probed_at: probedAt,
    results,
    any_failed: results.some(r => !r.ok),
    failed: results.filter(r => !r.ok).map(r => r.key)
  };

  // Persist every run for later analysis (one file per run keeps it simple).
  const safeTs = probedAt.replace(/[:.]/g, '-');
  const filename = path.join(TELEMETRY_DIR, `${safeTs}__probe.json`);
  try { fs.writeFileSync(filename, JSON.stringify(summary, null, 2)); } catch (_) {}

  // Compose a chat message that's only meaningful when something is wrong.
  const lines = ['*NAS-side health · ' + new Date(probedAt).toLocaleTimeString() + '*'];
  for (const r of results) {
    const icon = r.ok ? '🟢' : '🔴';
    const ms = r.ms != null ? ` (${r.ms}ms)` : '';
    const status = r.status ? ` [${r.status}]` : '';
    lines.push(`${icon} ${r.key}${status}${ms}${r.error ? ' — ' + r.error : ''}`);
  }

  return [{
    json: {
      ...summary,
      chat_text: lines.join('\n'),
      should_alert: summary.any_failed
    }
  }];
})();

// All probes green — quiet path. Return a no-op marker so the execution
// log shows why we didn't post (and we can search for 'all-green' to see
// healthy runs).
return [{ json: { skipped: true, reason: 'all-green-or-url-missing', ...$input.first().json } }];
